{"title":"Bioluminescent Jellyfish","code":"let jellyfish=[];
function setup(){
  createCanvas(windowWidth,windowHeight);
  colorMode(HSB,360,100,100,100);
  initJellyfish();
}
function initJellyfish(){
  jellyfish=[];
  for(let i=0;i<params.count;i++){
    jellyfish.push({
      x: random(width),
      y: random(height),
      angle: random(TWO_PI),
      size: random(40,80),
      phase: random(TWO_PI)
    });
  }
}
function draw(){
  // fade background for trailing effect
  background(0,0,10,params.bgAlpha);
  noStroke();
  fill(params.jellyColor);
  for(let j of jellyfish){
    // move gently upward with noise
    let t = frameCount*0.01*params.speed;
    j.x += (noise(j.x*0.001, j.y*0.001, t)-0.5)*2;
    j.y -= (0.5+noise(j.x*0.001, j.y*0.001, t+1000))*1.5*params.speed;
    // wrap around
    if(j.y < -j.size) j.y = height + j.size;
    if(j.x < -j.size) j.x = width + j.size;
    if(j.x > width + j.size) j.x = -j.size;
    // draw bell
    push();
    translate(j.x,j.y);
    rotate(sin(t + j.phase)*0.1);
    ellipse(0,0,j.size*1.2,j.size);
    // draw tentacles
    stroke(params.tentacleColor);
    strokeWeight(2);
    for(let k=0;k<8;k++){
      let a = map(k,0,8,0,TWO_PI)+PI/8;
      let len = j.size*params.tentacleLength;
      let off = sin(t*params.speed + k)*5;
      let x1 = cos(a)*j.size*0.6;
      let y1 = sin(a)*j.size*0.6;
      let x2 = x1 + cos(a+off)*len;
      let y2 = y1 + sin(a+off)*len;
      line(x1,y1,x2,y2);
    }
    pop();
  }
}
function windowResized(){
  resizeCanvas(windowWidth,windowHeight);
}
function keyPressed(){
  if(key==='r') initJellyfish();
}
