{"title":"Murmuration around Lighthouse","code":"let birds=[];
function setup(){
  createCanvas(windowWidth,windowHeight);
  initBirds();
}
function initBirds(){
  birds=[];
  for(let i=0;i<params.count;i++){
    birds.push({
      angle: random(TWO_PI),
      radius: random(50, min(width,height)/2),
      speed: random(0.5,1.5)*params.speed,
      size: random(2,params.maxSize)
    });
  }
}
function draw(){
  // background with fading trail
  background(params.bgColor);
  translate(width/2,height/2);
  // lighthouse center (invisible)
  let lighthousePos=createVector(0,0);
  // draw birds
  noStroke();
  fill(params.birdColor);
  for(let i=0;i<params.count;i++){
    let b=birds[i];
    // update angle and radius
    let dir = p5.Vector.sub(lighthousePos,createVector(b.radius*cos(b.angle),b.radius*sin(b.angle)));
    let dist = dir.mag();
    dir.normalize();
    // birds spiral inward then outward cyclically
    b.radius += sin(frameCount*0.01 + b.angle)*0.5*params.speed;
    b.angle += b.speed*0.02;
    // keep within bounds
    if(b.radius<30) b.radius=30;
    if(b.radius>min(width,height)/2-30) b.radius=min(width,height)/2-30;
    let x=b.radius*cos(b.angle);
    let y=b.radius*sin(b.angle);
    ellipse(x,y,b.size,b.size);
  }
}
function windowResized(){
  resizeCanvas(windowWidth,windowHeight);
  initBirds();
}
