{"title":"Moonlit Fireflies","code":"let fireflies=[];
function setup(){
  createCanvas(windowWidth,windowHeight);
  colorMode(HSB,360,100,100,1);
  for(let i=0;i<params.count;i++) fireflies.push(new Firefly());
}
function draw(){
  background(0,0,0,0.1); // fade trails
  for(let f of fireflies){
    f.update();
    f.show();
  }
}
function windowResized(){
  resizeCanvas(windowWidth,windowHeight);
}
class Firefly{
  constructor(){
    this.pos=createVector(random(width),random(height));
    this.vel=p5.Vector.random2D().mult(0.5);
    this.phase=random(TWO_PI);
  }
  update(){
    // wander with noise
    let angle=noise(this.pos.x*0.001, this.pos.y*0.001, frameCount*0.005*params.speed)*TWO_PI*2;
    let steer=p5.Vector.fromAngle(angle).setMag(0.3);
    this.vel.add(steer).limit(params.maxSpeed);
    this.pos.add(this.vel);
    // wrap around
    if(this.pos.x<0) this.pos.x+=width;
    if(this.pos.x>width) this.pos.x-=width;
    if(this.pos.y<0) this.pos.y+=height;
    if(this.pos.y>height) this.pos.y-=height;
    this.phase+=0.02*params.pulseSpeed;
  }
  show(){
    let glow=map(sin(this.phase),-1,1,0,1)*params.brightness;
    let col=color(params.hue,80,100,glow);
    noStroke();
    fill(col);
    ellipse(this.pos.x,this.pos.y,params.size);
  }
}
