{"title":"Jewel Fish Coral Flow","code":"let fish=[];
function setup(){
  createCanvas(windowWidth,windowHeight);
  initFish();
}
function initFish(){
  fish=[];
  for(let i=0;i<params.fishCount;i++){
    fish.push({
      pos:createVector(random(width),random(height)),
      vel:createVector(0,0),
      hue:random(360),
      size:params.fishSize
    });
  }
}
function draw(){
  background(params.bgColor);
  // update fish count if changed
  if(fish.length!==params.fishCount){
    initFish();
  }
  for(let f of fish){
    // move towards mouse with noise swirl
    let target=createVector(mouseX,mouseY);
    let dir=p5.Vector.sub(target,f.pos);
    dir.setMag(params.speed);
    // add Perlin noise for organic motion
    let n=noise(f.pos.x*0.005,f.pos.y*0.005,frameCount*0.01);
    let angle=map(n,0,1,-PI,PI);
    dir.rotate(angle*0.2);
    f.vel.lerp(dir,0.05);
    f.pos.add(f.vel);
    // wrap around edges
    if(f.pos.x<0)f.pos.x+=width;
    if(f.pos.x>width)f.pos.x-=width;
    if(f.pos.y<0)f.pos.y+=height;
    if(f.pos.y>height)f.pos.y-=height;
    // draw fish as jewel-colored ellipses with tail
    push();
    translate(f.pos.x,f.pos.y);
    rotate(f.vel.heading());
    let col=color(params.fishColor);
    col.setAlpha(200);
    fill(col);
    noStroke();
    // body
    ellipse(0,0,f.size*1.5,f.size);
    // tail
    triangle(-f.size*0.75,0,-f.size*1.2,-f.size*0.5,-f.size*1.2,f.size*0.5);
    pop();
  }
  // draw coral silhouette at center
  push();
  translate(width/2,height/2);
  fill(params.coralColor);
  noStroke();
  beginShape();
  let r=150;
  for(let a=0;a<TWO_PI;a+=PI/6){
    let rad=r+20*noise(a*0.5,frameCount*0.01);
    vertex(rad*cos(a),rad*sin(a));
  }
  endShape(CLOSE);
  pop();
}
function windowResized(){
  resizeCanvas(windowWidth,windowHeight);
}
