{"title":"Ink Plume in Milk","code":"let particles=[];
let cols, rows;
function setup(){
  createCanvas(windowWidth,windowHeight);
  cols = floor(width/20)+1;
  rows = floor(height/20)+1;
  // initialize max particles
  for(let i=0;i=params.plumeCount;i++){
    particles.push(new Particle());
  }
}
function draw(){
  background(params.bgColor);
  // adjust particle count dynamically
  while(particles.length<params.plumeCount) particles.push(new Particle());
  while(particles.length>params.plumeCount) particles.pop();
  for(let p of particles){
    p.update();
    p.show();
  }
}
function windowResized(){
  resizeCanvas(windowWidth,windowHeight);
}
class Particle{
  constructor(){
    this.pos=createVector(random(width),random(height));
    this.vel=createVector(0,0);
    this.age=0;
    this.maxAge=random(200,400)/params.speed;
  }
  update(){
    // flow field based on Perlin noise
    let n=noise(this.pos.x*0.005, this.pos.y*0.005, frameCount*0.001*params.speed);
    let angle=n*TWO_PI*params.swirlIntensity;
    let force=p5.Vector.fromAngle(angle);
    force.mult(0.5);
    this.vel.lerp(force,0.05);
    this.pos.add(this.vel);
    this.age++;
    if(this.age>this.maxAge || this.pos.x<0||this.pos.x>width||this.pos.y<0||this.pos.y>height){
      this.reset();
    }
  }
  reset(){
    this.pos.set(random(width),random(height));
    this.vel.set(0,0);
    this.age=0;
    this.maxAge=random(200,400)/params.speed;
  }
  show(){
    noStroke();
    let alpha=map(this.age,0,this.maxAge,255,0);
    fill(params.inkColor+hex(alpha,2));
    ellipse(this.pos.x,this.pos.y,params.size,params.size);
  }
}
